unsigned long xcrc16( unsigned char *ptr,
		      unsigned long  size,
		      unsigned long  crc )
{
    while(size-- != 0)
    {
	unsigned long i;
	unsigned long c=*ptr++;
	for( i=0; i<8; i++)
	{
	    if( (crc^c)&1 )
		crc = (crc>>1) ^ MAGIC16;
	    else
		crc = (crc>>1);
	    c>>=1;
	}
    }
    return crc & 0x0000FFFF;
}

unsigned long rcrc16( unsigned char *ptr,
		      unsigned long  size,
		      unsigned long  crc )
{
    while(size-- != 0)
    {
	unsigned long i;
	unsigned long c=ptr[size]<<8;
	for( i=0; i<8; i++)
	{
	    if( (crc^c)&0x8000 )
		crc = (crc<<1) ^ ((MAGIC16<<1)^1);
	    else
		crc = (crc<<1);
	    c<<=1;
	}
    }
    return crc & 0x0000FFFF;
}

unsigned long xcrc32( unsigned char *ptr,
		      unsigned long  size,
		      unsigned long  crc )
{
    crc = ~crc;
    while(size-- != 0)
    {
	unsigned long i;
	unsigned long c = *ptr++;
	for( i=0; i<8; i++)
	{
	    if (((crc^c)&1)!=0)
		crc = (crc>>1) ^ MAGIC32;
	    else
		crc = (crc>>1);
	    c>>=1;
	}
    }
    return ~crc;
}

unsigned long rcrc32( unsigned char *ptr,
		      unsigned long  size,
		      unsigned long  crc )
{
    crc = ~crc;
    while(size-- != 0)
    {
	unsigned long i;
	unsigned long c = ptr[size]<<24;
	for( i=0; i<8; i++)
	{
	    if (((crc^c)&0x80000000)!=0)
		crc = (crc<<1) ^ ((MAGIC32<<1)^1);
	    else
		crc = (crc<<1);
	    c<<=1;
	}
    }
    return ~crc;
}

