void fuckcrc16( unsigned char *ptr,
		unsigned long  size,
		unsigned long  offset,
		unsigned long  wantcrc,
		unsigned long  crc )
{
    *(unsigned short*)(ptr+offset) = xcrc16( ptr, offset, crc ) ^
     rcrc16( ptr+2+offset, size-(2+offset), rcrc16( (void*)&wantcrc, 2, 0
 );
