void cdecl printf(pchar format, ...)
  {
    dword stack_ptr = 12;

    asm
	mov	esi, format
	cld
__nextchar:
	lodsb
	or	al, al
	jz	__exit
	cmp	al, '%'
	je	__percent
	cmp	al, 0x0A
	je	__crlf

__putchar:
	push	eax
	call	printf_char

	jmp	__nextchar

__crlf: call	printf_crlf

	jmp	__nextchar

em_pop_eax:
	mov	ecx, stack_ptr
	add	stack_ptr, 4
	mov	eax, [ebp+ecx]
	ret

__percent:
	lodsb
	or	al, al
	jz	__exit

	cmp	al, 's'
	je	__s
	cmp	al, 'i'
	je	__i
	cmp	al, 'l'
	je	__l
	cmp	al, 'c'
	je	__c
	cmp	al, 'b'
	je	__b
	cmp	al, 'w'
	je	__w
	cmp	al, 'd'
	je	__d
	cmp	al, 'B'
	je	__bh
	cmp	al, 'W'
	je	__wh
	cmp	al, 'D'
	je	__dh
	cmp	al, 'a'
	je	__a

	jmp	__putchar

__s:	call	em_pop_eax
	push	eax
	call	printf_short
	jmp	__nextchar

__i:	call	em_pop_eax
	push	eax
	call	printf_int
	jmp	__nextchar

__l:	call	em_pop_eax
	push	eax
	call	printf_long
	jmp	__nextchar

__c:	call	em_pop_eax
	push	eax
	call	printf_char
	jmp	__nextchar

__b:	call	em_pop_eax
	push	eax
	call	printf_byte
	jmp	__nextchar

__w:	call	em_pop_eax
	push	eax
	call	printf_word
	jmp	__nextchar

__d:	call	em_pop_eax
	push	eax
	call	printf_dword
	jmp	__nextchar

__bh:	call	em_pop_eax
	push	eax
	call	printf_hexbyte
	jmp	__nextchar

__wh:	call	em_pop_eax
	push	eax
	call	printf_hexword
	jmp	__nextchar

