quit:                                       ;
       lea edi, str5                        ;
       call write_string                    ;
                                            ;
       push 0                               ; exit
       call ExitProcess                     ;
                                            ;
compression_error:                          ;
       cmp eax, 3                           ;
       jne not__1                           ;
       lea edi, compe1                      ;
       call write_string                    ;
                                            ;
not__1:                                     ;
       mov fail, 1                          ;
       jmp close_files_1                    ;
                                            ;
decompression_error:                        ;
       cmp eax, 3                           ;
       jne not__2                           ;
       lea edi, decoe1                      ;
       call write_string                    ;
       jmp not__4                           ;
                                            ;
not__2:                                     ;
       cmp eax, 4                           ;
       jne not__3                           ;
       lea edi, decoe2                      ;
       call write_string                    ;
       jmp not__4                           ;
                                            ;
not__3:                                     ;
       cmp eax, 5                           ;
       jne not__4                           ;
       lea edi, decoe3                      ;
       call write_string                    ;
                                            ;
not__4:                                     ;
       mov fail, 1                          ;
       jmp close_files_2                    ;
                                            ;
write_string:                               ;write string to dos screen
; EDI = pointer to ACIIZ string             ;
                                            ;
       push edi                             ;
       call lstrlen                         ;
                                            ;
       push 0                               ;
       push offset nob                      ;
       push eax                             ;
       push edi                             ;
       push dchandle                        ;
       call WriteFile                       ;
       ret                                  ;
                                            ;
ExceptionExit:                              ;
       mov esp, [esp+8]                     ;if some GPF occured...
       pop dword ptr fs:[0]                 ;
       add esp, 4                           ;
       lea edi, str6                        ;
       call write_string                    ;
       jmp quit                             ;

