		return -1;
	}			

	CloseHandle(new_thread);

	/* pak by tady mohla bejt komunikacni trubka na potvrzeni prenosu */

	send(*socket, "\r\nPrenos byl zahajen na portu: ", 31,0);
	send(*socket, port, lstrlen(port),0);
